import sys
import os
import math

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def get_divisors(n):
    """Get all divisors of n."""
    divisors = []
    for i in range(1, int(math.isqrt(n)) + 1):
        if n % i == 0:
            divisors.append(i)
            if i != n // i:
                divisors.append(n // i)
    return sorted(divisors)

def calculate_moves(a, k):
    """
    Calculate minimum moves to make all boxes divisible by k.
    We process from left to right, accumulating prefix sums.
    The cost for each prefix is abs(prefix_sum % k).
    """
    total_moves = 0
    prefix_sum = 0
    for x in a:
        prefix_sum += x
        total_moves += prefix_sum % k
    return total_moves

def solution(input_str):
    try:
        lines = input_str.strip().split('\n')
        n = int(lines[0])
        a = list(map(int, lines[1].split()))

        total_sum = sum(a)

        # Edge case: n=1 with small positive value
        if n == 1 and total_sum <= 1:
            return "-1"

        # If n=1, we can't move anything to other boxes
        if n == 1:
            return "-1"

        # Find all divisors of total_sum
        divisors = get_divisors(total_sum)

        # Find minimum moves for any valid divisor k > 1
        # Filter out k = 1 (Alice needs k > 1)
        ans = float('inf')

        for k in divisors:
            if k > 1:
                moves = calculate_moves(a, k)
                ans = min(ans, moves)

        if ans == float('inf'):
