```python
def solution(input_str):
    parts = input_str.strip().split('\n')
    first_line = parts[0].split()
    n, k = int(first_line[0]), int(first_line[1])
    a = list(map(int, parts[1].split()))

    def f(x):
        """Divide out all factors of k"""
        while x % k == 0:
            x //= k
        return x

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def can_solve_and_get_path(tup):
        """Returns (can_solve, path) tuple"""
        if len(tup) == 1:
            if tup[0] == 1:
                return (True, [])
            return (False, None)

        # Try combining all pairs
        for i in range(len(tup)):
            for j in range(i + 1, len(tup)):
                new_val = f(tup[i] + tup[j])
                new_list = list(tup[:i] + tup[i+1:j] + tup[j+1:] + [new_val])
                new_tup = tuple(sorted(new_list))

                can, path = can_solve_and_get_path(new_tup)
                if can:
                    return (True, [(i, j)] + path)

        return (False, None)

    initial_tup = tuple(sorted(a))
    can_solve, path = can_solve_and_get_path(initial_tup)

    if not can_solve:
        return "NO"

    result = ["YES"]
    for i, j in path:
        result.append(f"{i} {j}")

    for line in result:
        return '\n'.join(result)
