    """
    Solve the microwave bananas problem.

    At each time-step, we either add or multiply bananas in the microwave,
    finding when we can first reach exactly j bananas for each j from 1 to m.

    Args:
        input_str: String containing n, m and n operation lines

    Returns:
        String with m space-separated integers (earliest step to get j bananas or -1)
    """
    lines = input_str.strip().split('\n')
    if len(lines) < 1:
        return '-1 ' * int(input_str.split()[1]) + '\n'

    try:
        n, m = map(int, lines[0].split())
    except:
        return '\n'

    ops = []
    for i in range(1, n + 1):
        if i >= len(lines):
            break
        try:
            parts = lines[i].split()
            if len(parts) != 3:
                break
            t, xp, y = map(int, parts)
            x = xp / 100000.0
            ops.append((t, x, y))
        except:
            break

    ans = [-1] * (m + 1)
    reachable = {0}
    ans[0] = 0

    for step in range(1, n + 1):
        if step > len(ops):
            break
        t, x, y = ops[step - 1]
        next_reachable = set(reachable)

        for k in list(reachable):
            if t == 1:
                # Type 1: ceil(k + x) for each of up to y steps
                # Since k is integer: ceil(k + x) = k + ceil(x)
                add = int(-(-x))  # ceilling of x using math formula
                for a in range(1, y + 1):
                    new_k = k + a * add
                    if new_k > m:
                        break
                    next_reachable.add(new_k)
            else:
                # Type 2: ceil(k * x) for each of up to y steps
                for a in range(1, y + 1):
                    # Use small epsilon for ceiling with floating point
                    new_k = int(k * x + 1e-10)
                    if new_k > m:
                        break
                    next_reachable.add(new_k)

        reachable = next_reachable

        # Track the earliest step we can reach each banana count
        for k in reachable:
            if ans[k] == -1:
                ans[k] = step

    return ' '.join(map(str, ans[1:])) + '\n'
