        return ["passed"]

def solution(input_str):
    n, m = map(int, input_str.strip().split())

    # Special case: 2×2 board has max distance 2, can't place any chessmen
    if n * m == 4:
        return "0\n"

    # 1D board (n=1 or m=1): pairs at distance 3
    if min(n, m) == 1:
        max_dim = max(n, m)
        return str(2 * (max_dim // 3)) + "\n"

    # 2×m board where m >= 3
    elif min(n, m) == 2:
        return str(n * m - 2) + "\n"

    # Both dimensions >= 3
    else:
        return str(n * m - 1) + "\n"
