def solve(n, k):
    # Check if n is a sum (at positions k+1, 2*(k+1), 3*(k+1), ...)
    # Sum formula: k*r*(r+1) where r is the round number
    q = (k * 2) ** 0.5

    # For sum check: n = k*r*(r+1)
    # Solve quadratic: r^2 + r - n/k = 0
    # r = (-1 + sqrt(1 + 4n/k)) / 2

    if n % k == 0 and n // k > 0:
        target = n // k
        delta = 1 + 4 * target
        if delta >= 0:
            sqrt_delta = int(delta ** 0.5)
            if sqrt_delta * sqrt_delta == delta and (sqrt_delta - 1) % 2 == 0:
                r = (sqrt_delta - 1) // 2
                if k * r * (r + 1) == n:
                    return r * (k + 1)

    # Binary search for the round
    low = 1
    high = 2 * 10**9
    idx = -1

    while low <= high:
        mid = (low + high) // 2
        # Maximum value after mid rounds
        max_val = k * mid + mid * (mid - 1) // 2
        if max_val >= n:
            idx = mid
            high = mid - 1
        else:
            low = mid + 1

    r = idx

    # Calculate position within round
    positions_per_round = k + 1
    offset = n - r * (r - 1) * k
    if offset <= k:
        return (r - 1) * (k + 1) + offset
    else:
        return r * (k + 1)

