Looking at this problem, I need to find a minimum-weight spanning tree with exactly k edges incident to vertex 1 (the capital).

## Solution Strategy

The key insight is that we need to:
1. Select exactly k edges that connect to vertex 1
2. Complete a spanning tree with n-1 total edges
3. Minimize total weight

I'll use a modified Kruskal's approach:
1. Separately collect edges incident to vertex 1 vs. other edges
2. Greedily select the k cheapest incident edges to satisfy the constraint
3. Complete the spanning tree with other edges
4. Verify all vertices are connected

```python
def solution(input_str):
    lines = input_str.strip().split('\n')

    n, m, k = map(int, lines[0].split())

    edges = []
    for i in range(m):
        u, v, w = map(int, lines[1 + i].split())
        edges.append((u, v, w, i + 1))

    # Special case: single city needs no roads
    if n == 1:
        return "0\n\n"

    # Edge case: k exceeds maximum possible
    if k > n - 1:
        return "-1\n"

    # Separate incident and non-incident edges
    incident = [(u, v, w, idx) for u, v, w, idx in edges if u == 1 or v == 1]
    non_incident = [(u, v, w, idx) for u, v, w, idx in edges if u != 1 and v != 1]

    # Sort by weight for greedy selection
    incident.sort(key=lambda x: x[2])
    non_incident.sort(key=lambda x: x[2])

    # Union-Find structures
    parent = list(range(n + 1))
    rank = [0] * (n + 1)

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return False
        if rank[px] < rank[py]:
            px, py = py, px
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
        return True

    selected = []

    # Phase 1: Select exactly k incident edges greedily
    k_needed = k
    for u, v, w, idx in incident:
        if k_needed <= 0:
            break
        if union(u, v):
            selected.append(idx)
            k_needed -= 1

    # Phase 2: Complete spanning tree if we have incident edges
    for idx in selected:
        pass  # already selected

    # Continue with remaining needed edges
    needed = n - 1 - len(selected)
    idx_to_add = len(selected)

    # Added incident edges, now add others
    for u, v, w, idx in non_incident:
        if needed <= 0:
            break
        if union(u, v):
            selected.append(idx)
            needed -= 1

    # Phase 3: Fill any remaining if we need exactly k incident
    while len(selected) < n - 1:
        for u, v, w, idx in non_incident:
            if find(u) != find(v):
                parent[find(u)] = find(v)
                selected.append(idx)
                break
        else:
            continue
        break

    # Final verification
    if len(selected) < n - 1:
        return "-1\n"

    # Verify connectivity using union-find
    roots = set()
    for i in range(1, n + 1):
        parent[i] = i
        if i != 1 and find(i) != find(1):
            return "-1\n"

    # Output result
    return f"{len(selected)}\n" + " ".join(map(str, selected))
