    return wrapper

def count_solutions(m, b, n):
    """
    Count non-negative integer solutions to:
    a_0 + a_1*b + a_2*b^2 + ... + a_{n-1}*b^{n-1} = m

    This is equivalent to finding how many ways we can represent m
    in base b with exactly n digits (including leading zeros).
    """
    @lru_cache(None)
    def dp(rem, deg):
        if rem == 0:
            return 1
        if deg < 0:
            return 0

        power = b ** deg
        if power > rem:
            return 0

        ans = 0
        max_a = rem // power

        for a in range(max_a + 1):
            ans = (ans + dp(rem - a * power, deg - 1)) % MOD

        return ans

    return dp(m, n - 1)

from functools import lru_cache

def solve(m, b, n):
    """
    Solve the polynomial coefficient problem.
    Find number of polynomials of degree at most (n-1) with non-negative integer
    coefficients such that P(b) = m.
    """
    if n <= 0:
        return 0 if m != 0 else 1

    if b == 1:
        # Special case: a_0 + a_1 + ... + a_{n-1} = m
        # Using stars and bars: C(m + n - 1, n - 1)
        if m < 0 or n < 1:
            return 0
        return comb(m + n - 1, n - 1)

    # For b > 1, use digit DP
    return count_solutions(m, b, n)

