    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    if k > n // 2:
        k = n - k

    result = 1
    for i in range(k):
        result = (result * (n - i)) % MOD
        result = (result * pow(i + 1, MOD - 2, MOD)) % MOD
    return result

