                if check_set(a_s, b_s, threshold if i < 4 else 15):
                    sets.append((A_score + a_s, B_score + b_s))
                    A_score += a_s
                    B_score += b_s
                    continue

        # Team B wins
        if target_a - A_score >= threshold - 1 and (target_b - B_score < 0 or 2):
            continue

        b_s = min(threshold, target_b - B_score)
        if b_s < threshold:
